export interface TimedValue {
  timestamp: number
  payload: string
}
export class WindowCache {
  private values: Map<string, TimedValue> = new Map()
  constructor(private limit: number) {}
  store(token: string, text: string): void {
    this.values.set(token, { timestamp: Date.now(), payload: text })
    if (this.values.size <= this.limit) { return }
    let selected: string | undefined = undefined
    let minimum: number = Number.MAX_SAFE_INTEGER
    for (const [entryKey, entryValue] of this.values) {
      if (entryValue.timestamp < minimum) {
        minimum = entryValue.timestamp
        selected = entryKey
      }
    }
    if (selected !== undefined) { this.values.delete(selected) }
  }
}

